/* ==== style ==== */
:root{
--white:#fff}
*{box-sizing:border-box}
body{margin:0;
font-size:14px;
font-weight:400}
button,input,select,textarea{font:inherit}
button{cursor:pointer}
button:disabled{opacity:.45;
cursor:not-allowed}
a{color:inherit;
text-decoration:none}
svg{display:block}
#app{min-height:100vh}
.shell{
min-height:100vh}
.sidebar{
position:fixed;
top:0;
left:0;
bottom:0;
overflow-y:auto;
z-index:10}
.nav-btn{display:flex;
align-items:center;
width:100%;
background:transparent;
margin-bottom:3px;
text-align:left}
.nav-btn svg{
stroke-width:1.8}
.main{
min-width:0}
.top-actions{
flex-wrap:wrap}
.date-chip{display:inline-flex;
align-items:center;
gap:8px;
background:white;
border:1px solid var(--line);
white-space:nowrap}
.btn{border:1px solid transparent;
background:var(--blue);
color:white;
padding:10px 14px;
font-size:12px;
display:inline-flex;
align-items:center;
gap:8px;
justify-content:center;
white-space:nowrap}
.btn svg{width:15px;
height:15px}
.btn.ghost{background:#fff;
border-color:#dce4ef}
.btn.soft{background:var(--blue2);
color:var(--blue)}
.btn.danger{background:#fff2f3;
color:#ba3c52;
border-color:#ffe0e4}
.btn.sm{padding:7px 10px;
min-height:31px;
font-size:11px}
.btn.round{border-radius:50%;
width:34px;
height:34px;
padding:0}
.grid{display:grid;
gap:16px}
.kpis{grid-template-columns:repeat(4,minmax(0,1fr))}
.kpi{background:#fff;
border:1px solid var(--line);
box-shadow:var(--shadow);
min-width:0;
position:relative;
overflow:hidden}
.kpi-head{display:flex;
align-items:center;
justify-content:space-between;
gap:8px;
font-weight:630}
.kpi-icon{width:34px;
height:34px;
display:grid;
place-items:center}
.kpi-icon svg{width:18px;
height:18px}
.kpi-value{
font-weight:810;
white-space:nowrap;
overflow:hidden;
text-overflow:ellipsis}
.kpi-foot{color:#91a0b6;
margin-top:9px}
.positive{color:var(--green)!important}
.negative{color:var(--red)!important}
.section-title{display:flex;
align-items:flex-start;
justify-content:space-between;
gap:15px;
margin-bottom:14px}
.section-title h2{
margin:0;
font-weight:780}
.section-title p{margin:5px 0 0;
color:var(--muted);
font-size:12px}
.panel{background:white;
border:1px solid var(--line);
box-shadow:var(--shadow);
min-width:0}
.panel.no-pad{padding:0;
overflow:hidden}
.columns{grid-template-columns:minmax(0,1.6fr) minmax(295px,1fr);
align-items:stretch}
.columns.equal{grid-template-columns:repeat(2,minmax(0,1fr))}
.panel-head{display:flex;
align-items:center;
justify-content:space-between;
gap:12px;
margin-bottom:16px}
.panel-head h3{
margin:0;
font-weight:760}
.subtle{color:var(--muted);
font-size:12px}
.mini-row{display:flex;
justify-content:space-between;
align-items:center;
gap:9px;
padding:12px 0;
border-bottom:1px solid #f0f2f6}
.mini-row:last-child{border:0}
.mini-title{font-weight:690;
font-size:12px}
.mini-sub{font-size:11px;
color:var(--muted);
margin-top:4px}
.money{font-weight:770;
font-variant-numeric:tabular-nums;
white-space:nowrap}
.pill{display:inline-flex;
align-items:center;
gap:5px;
font-size:10px;
font-weight:750;
white-space:nowrap;
background:#f0f4fb;
color:#62718a}
.pill.green{background:#e6f8f0;
color:#0d8d65}
.pill.red{background:#ffecef;
color:#c3455c}
.pill.orange{background:#ffe5e9;
color:#ac2239}
.pill.blue{background:#ecf1ff;
color:#315de1}
.progress{height:7px;
background:#ebeff5;
border-radius:99px;
overflow:hidden;
margin-top:11px}
.progress>span{display:block;
height:100%;
border-radius:99px;
background:var(--blue)}
.progress>span.warn{background:var(--orange)}
.progress>span.high{background:var(--red)}
.amount-line{display:flex;
align-items:flex-end;
justify-content:space-between;
gap:7px}
.empty{padding:34px 20px;
text-align:center;
color:#8c99ae;
font-size:12px;
line-height:1.7}
.empty-icon{font-size:25px;
display:block;
margin-bottom:9px;
opacity:.65}
.cards-grid{grid-template-columns:repeat(auto-fill,minmax(270px,1fr))}
.bank-card{border:1px solid var(--line);
padding:18px;
background:white;
box-shadow:var(--shadow);
min-width:0}
.bank-card .name{font-weight:750;
font-size:14px}
.bank-card .type{font-size:11px;
color:var(--muted);
margin-top:5px}
.bank-card .big{font-size:24px;
letter-spacing:-.8px;
font-weight:790;
margin-top:22px}
.bank-card .bottom{display:flex;
align-items:center;
justify-content:space-between;
gap:10px;
margin-top:18px}
.card-visual{padding:20px;
border-radius:17px;
min-height:183px;
color:#fff;
background:linear-gradient(128deg,#152a4b 0%,#273e74 65%,#4774ce 120%);
position:relative;
overflow:hidden;
box-shadow:0 10px 25px #20396624}
.card-visual:before{content:'';
position:absolute;
width:235px;
height:235px;
border:1px solid #ffffff17;
border-radius:50%;
right:-75px;
top:-90px}
.card-visual:after{content:'';
position:absolute;
width:170px;
height:170px;
border:1px solid #ffffff19;
border-radius:50%;
right:-55px;
top:-45px}
.card-visual .chip{margin-top:28px;
display:block;
width:28px;
height:19px;
border:1px solid #e79ca9;
border-radius:4px;
background:linear-gradient(90deg,#d98290,#efadb8)}
.card-visual .last4{font-size:20px;
letter-spacing:3px;
margin-top:10px;
position:relative}
.card-visual .bottom{font-size:11px;
color:#c1d5f5;
position:relative;
margin-top:14px}
.dual{display:grid;
grid-template-columns:1fr 1fr;
gap:12px}
.small-label{font-size:10px;
letter-spacing:.2px;
color:#8190a7}
.card-footer{display:flex;
justify-content:space-between;
align-items:center;
gap:8px;
margin-top:12px}
.table-wrap{
width:100%}
table{
width:100%;
white-space:nowrap;
font-variant-numeric:tabular-nums}
th{text-align:left;
color:#71809a;
font-size:11px;
letter-spacing:.12px;
font-weight:740;
border-bottom:1px solid var(--line);
padding:13px 14px}
td{padding:13px 14px;
font-size:12px;
border-bottom:1px solid #edf1f6}
tbody tr:last-child td{border-bottom:0}
tbody tr:hover{background:#fafcff}
td .subtitle{font-size:10px;
color:var(--muted);
margin-top:4px}
.right{text-align:right}
.annual-table{min-width:1160px}
.annual-table th,.annual-table td{padding:11px 10px}
.annual-table td:not(:first-child),.annual-table th:not(:first-child){text-align:right}
.annual-table .group td{background:#eef3fd;
color:#254879;
font-size:12px;
font-weight:810}
.annual-table .sum td{background:#f4f7fc;
font-weight:770}
.annual-table .ending td{background:#e9f5f0;
font-weight:790;
color:#13755f}
.annual-table .light{color:#9eaabe}
.filters{display:flex;
align-items:center;
flex-wrap:wrap;
gap:10px}
.field,.filter-select{
color:var(--ink);
padding:10px 11px;
outline:0;
width:100%}
.filter-select{width:auto;
min-width:125px}
.filter-label{font-size:11px;
font-weight:720;
color:#64748c;
display:block;
margin-bottom:6px}
.form-grid{display:grid;
grid-template-columns:1fr 1fr;
gap:14px}
.form-full{grid-column:1/-1}
.form-foot{margin-top:20px;
display:flex;
justify-content:flex-end;
gap:9px;
border-top:1px solid var(--line);
padding-top:18px}
.form-note{font-size:11px;
color:#7d8ba2;
line-height:1.6}
.modal-layer{position:fixed;
inset:0;
z-index:40;
display:flex;
justify-content:center;
align-items:flex-start;
overflow:auto;
padding:45px 16px}
.modal{background:white;
width:min(640px,100%);
padding:23px}
.modal.wide{width:min(780px,100%)}
.modal-head{display:flex;
justify-content:space-between;
align-items:center;
margin-bottom:18px}
.modal-head h2{font-size:18px;
margin:0}
.close{border:0;
background:#f3f5f9;
border-radius:9px;
width:30px;
height:30px;
color:#64718a;
font-size:20px}
.form-section{font-size:12px;
font-weight:760;
color:#31486d;
border-bottom:1px solid #e6eaf2;
padding:8px 0;
margin:6px 0 11px}
.notification{border-radius:12px;
padding:12px 15px;
font-size:12px;
line-height:1.6;
border:1px solid #dce8fa;
background:#edf3ff;
color:#476189;
margin-bottom:15px}
.notification.warning{background:#ffe9ed;
border-color:#f5c0c9;
color:#932134}
.notification.danger{background:#fff0f0;
border-color:#f5d9df;
color:#b2475b}
.notification.success{background:#edf9f4;
border-color:#d2efdf;
color:#13775d}
.toast{position:fixed;
bottom:26px;
right:25px;
background:#142743;
color:#fff;
padding:14px 18px;
border-radius:12px;
box-shadow:0 10px 35px #131e3340;
z-index:70;
max-width:350px;
font-size:12px}
.hstack{display:flex;
align-items:center;
gap:9px;
flex-wrap:wrap}
.gap{height:12px}
.muted{color:var(--muted)}
.tiny{font-size:11px}
.activity-icon{width:34px;
height:34px;
display:grid;
place-items:center;
border-radius:9px;
background:#f1f4fa;
font-size:15px;
flex-shrink:0}
.listitem{display:flex;
align-items:center;
gap:12px;
border-bottom:1px solid #eff2f6;
padding:12px 0}
.listitem:last-child{border:0}
.listitem-content{min-width:0;
flex:1}
.listitem-title{font-size:12px;
font-weight:700;
overflow:hidden;
text-overflow:ellipsis;
white-space:nowrap}
.listitem-sub{font-size:11px;
color:#8b98ab;
margin-top:4px}
.plot{width:100%;
min-height:230px}
.plot svg{width:100%;
height:auto}
.legend{display:flex;
gap:15px;
align-items:center;
flex-wrap:wrap}
.legend span{font-size:10px;
color:#76869d;
display:inline-flex;
gap:6px;
align-items:center}
.dot{width:8px;
height:8px;
border-radius:50%;
display:inline-block}
.donut{border-radius:50%;
width:165px;
height:165px;
margin:auto;
position:relative}
.donut:after{content:'';
position:absolute;
inset:29px;
background:#fff;
border-radius:50%}
.category-row{display:flex;
align-items:center;
justify-content:space-between;
font-size:11px;
margin:10px 0;
gap:9px}
.category-row .bar{height:6px;
background:#edf1f6;
flex:1;
border-radius:20px;
overflow:hidden;
min-width:30px}
.category-row .bar span{height:100%;
display:block;
border-radius:20px}
.stats-inline{display:grid;
grid-template-columns:repeat(3,1fr);
gap:12px}
.stat-box{padding:15px;
background:#f7f9fd;
border:1px solid #edf0f6;
border-radius:12px}
.stat-box .val{font-size:20px;
font-weight:790;
margin:10px 0 3px}
.mini-divider{height:1px;
background:var(--line);
margin:16px 0}
.split{display:flex;
justify-content:space-between;
align-items:center;
gap:12px}
.tabs{display:flex;
background:#edf2fa;
padding:4px;
border-radius:10px;
gap:2px;
flex-wrap:wrap}
.tab{border:0;
background:transparent;
color:#6c7d98;
font-size:11px;
font-weight:730;
border-radius:8px;
padding:8px 12px}
.tab.active{background:white;
color:#254fd5;
box-shadow:0 1px 5px #a8b7cb33}
.footnote{color:#9aa7b7;
font-size:10px;
line-height:1.6;
margin-top:10px}
.budget-row{padding:12px 0;
border-bottom:1px solid var(--line)}
.budget-row:last-child{border-bottom:0}
.year-control{font-size:12px;
font-weight:730;
border:1px solid var(--line);
background:#fff;
border-radius:9px;
padding:10px}
.hidden{display:none!important}
.searchbox{min-width:210px}
.input-error{color:var(--red);
font-size:11px;
margin-top:7px}
.card-detail{margin-top:16px;
border-top:1px solid var(--line);
padding-top:16px}
.statement-detail{background:#f7f9fe;
border-radius:12px;
padding:13px;
margin:11px 0}
.statement-detail .amount{font-size:17px;
font-weight:790}
.outline-box{padding:17px;
border:1px solid var(--line);
border-radius:13px;
background:#fff}
.linkish{color:var(--blue);
font-weight:720;
cursor:pointer;
border:0;
background:none;
font-size:11px}
.mobile-bar{display:none}
@media(max-width:1200px){.kpis{grid-template-columns:repeat(2,minmax(0,1fr))}
.columns{grid-template-columns:1fr}
.main{padding:23px}
.stats-inline{grid-template-columns:repeat(3,1fr)}
}
@media(max-width:790px){.sidebar{position:static;
height:auto;
padding:9px 10px;
display:none}
.sidebar.open{display:block;
position:fixed;
bottom:0;
top:55px;
overflow:auto}
.main{margin-left:0}
.mobile-bar button{
padding:8px}
.date-chip{display:none}
.kpis{gap:10px}
.form-grid,.columns.equal,.dual{grid-template-columns:1fr}
.stats-inline{grid-template-columns:1fr 1fr}
.searchbox{min-width:0;
width:100%}
}
@media(max-width:420px){.kpis{grid-template-columns:1fr}
.stats-inline{grid-template-columns:1fr}
.top-actions{width:100%}
.btn{flex:1}
}
@media print{.sidebar,.mobile-bar,.top-actions,.btn,.filters{display:none!important}
.panel,.kpi{box-shadow:none}
.shell{display:block}
}

/* vive el hoy V2 · NUEVA CAPA VISUAL */
.brand{padding-bottom:28px}
.top-sub{
max-width:580px}
.btn{
min-height:40px}
.btn:focus-visible,.institution-tile:focus-visible,.product-item:focus-visible{outline:3px solid #94b5ff;
outline-offset:3px}
.kpi,.panel,.bank-card{border:1px solid #e9edf4;
border-radius:20px;
box-shadow:0 7px 30px rgba(33,52,87,.04)}
.kpi-icon{
color:#5873c8}
.section-title h2{
letter-spacing:-.45px}
.bank-hero{display:flex;
justify-content:space-between;
gap:30px;
align-items:stretch;
background:linear-gradient(125deg,#132c55 0%,#172b4d 48%,#263d65 100%);
border:1px solid #254165;
border-radius:23px;
color:white;
padding:36px 38px;
position:relative;
overflow:hidden;
isolation:isolate}
.bank-hero:after{content:'';
position:absolute;
width:420px;
height:420px;
border:1px solid rgba(153,185,242,.17);
border-radius:50%;
right:-155px;
top:-250px;
box-shadow:0 0 0 54px rgba(108,153,228,.034),0 0 0 120px rgba(108,153,228,.026);
z-index:-1}
.hero-eyebrow{font-size:10px;
font-weight:760;
letter-spacing:2px;
color:#a4c1ec;
margin-bottom:15px}
.bank-hero h2{font-size:clamp(27px,3.2vw,40px);
line-height:1.12;
font-weight:775;
letter-spacing:-1.6px;
margin:0}
.bank-hero h2 em{font-style:normal;
color:#8aaffd}
.bank-hero p{font-size:12.8px;
line-height:1.8;
max-width:560px;
margin:18px 0 22px}
.hero-actions{display:flex;
gap:9px;
flex-wrap:wrap}
.btn.light{background:#fff;
color:#183258}
.btn.outline-light{background:transparent;
border-color:#6f87a5;
color:#e9f0fa}
.institution-grid{display:grid;
grid-template-columns:repeat(3,minmax(0,1fr));
gap:15px}
.institution-tile{display:flex;
flex-direction:column;
gap:3px;
min-width:0;
text-align:left;
border:1px solid #e6ebf3;
background:#fff;
box-shadow:0 7px 24px rgba(34,52,83,.035);
border-radius:18px;
padding:20px 20px 17px;
transition:.17s}
.institution-tile:hover{border-color:#adc4f2;
transform:translateY(-3px);
box-shadow:0 13px 27px rgba(43,79,143,.1)}
.institution-tile.selected{border-color:#789af6;
box-shadow:0 0 0 3px #dae5ff}
.institution-top{display:flex;
align-items:flex-start;
justify-content:space-between;
margin-bottom:16px}
.institution-logo{width:44px;
height:44px;
display:grid;
place-items:center;
border-radius:13px;
color:#fff;
font-size:14px;
font-weight:800;
letter-spacing:-.3px}
.institution-logo.large{width:54px;
height:54px;
border-radius:16px;
font-size:16px}
.institution-arrow{width:28px;
height:28px;
display:grid;
place-items:center;
color:#94a3b8;
background:#f4f6fa;
border-radius:9px}
.institution-arrow svg{width:15px;
height:15px}
.institution-name{font-size:16px;
font-weight:800;
letter-spacing:-.5px;
color:#162741}
.institution-type{color:#8492a7;
font-size:11px;
margin-top:3px}
.institution-rule{height:1px;
background:#edf0f5;
margin:17px 0 13px}
.institution-metrics{display:grid;
grid-template-columns:1fr 1fr;
gap:8px}
.institution-metrics>div{display:flex;
flex-direction:column;
gap:7px;
min-width:0}
.institution-metrics span{color:#8593a9;
font-size:10px}
.institution-metrics strong{color:#293e5d;
font-size:13px;
font-variant-numeric:tabular-nums;
overflow:hidden;
text-overflow:ellipsis}
.empty-bank{grid-column:1/-1;
text-align:center;
border:1px dashed #bac9e0;
background:linear-gradient(145deg,#fff,#f7faff);
border-radius:20px;
padding:46px 25px}
.empty-bank-art{display:grid;
place-items:center;
background:#ecf2ff;
color:#466ee9;
border-radius:20px;
width:60px;
height:60px;
margin:0 auto 14px}
.empty-bank-art svg{width:31px}
.empty-bank h3{margin:0 0 8px;
font-size:19px}
.empty-bank p{max-width:450px;
margin:0 auto 20px;
color:#7b889e;
line-height:1.6}
.empty-bank .btn{margin:4px}
.bank-workspace{background:#fff;
border:1px solid #e3eafa;
box-shadow:0 15px 50px rgba(35,70,125,.06);
border-radius:22px;
margin-top:23px;
padding:25px;
scroll-margin-top:25px}
.workspace-title{display:flex;
justify-content:space-between;
align-items:center;
gap:15px;
margin-bottom:21px}
.workspace-title h2{font-size:24px;
letter-spacing:-.8px;
margin:0}
.workspace-title p{font-size:11px;
color:#8291a6;
margin:5px 0 0;
max-width:600px}
.bank-workspace .kpi{box-shadow:none;
background:#f8faff}
.product-columns{display:grid;
grid-template-columns:repeat(3,minmax(0,1fr));
gap:14px}
.product-lane{min-width:0;
border:1px solid #e6eaf2;
border-radius:15px;
overflow:hidden;
background:#fff}
.lane-head{padding:13px 15px;
background:#f7f9fd;
display:flex;
gap:9px;
align-items:center;
font-weight:775;
font-size:12px;
border-bottom:1px solid #ecf0f5}
.lane-head svg{width:16px;
height:16px;
color:#5c79c9}
.lane-head span{background:#e7eefc;
border-radius:99px;
margin-left:auto;
padding:3px 9px;
color:#526b95;
font-size:10px}
.product-item{width:100%;
border:0;
border-bottom:1px solid #f0f2f7;
background:transparent;
display:flex;
align-items:center;
justify-content:space-between;
text-align:left;
padding:14px 13px;
gap:10px}
.product-item:hover{background:#f7faff}
.product-item span{min-width:0}
.product-item strong{display:block;
color:#2a3953;
font-size:12px;
overflow-wrap:anywhere}
.product-item small{display:block;
color:#8b98a9;
font-size:10px;
margin-top:6px}
.product-item b{color:#4761a2;
font-size:11px;
text-align:right;
max-width:48%;
overflow-wrap:anywhere}
.lane-empty{color:#a0acbd;
padding:30px 12px;
font-size:11px;
text-align:center}
.hierarchy>div{display:flex;
align-items:center;
flex-wrap:wrap;
gap:10px;
border-bottom:1px solid #edf1f6;
padding:17px 0}
.hierarchy>div:last-child{border-bottom:0}
.hier-num{font-size:10px;
color:#6689ea;
background:#edf2ff;
border-radius:7px;
padding:8px;
font-weight:800}
.hierarchy strong{font-size:12px}
.hierarchy small{margin-left:auto;
font-size:10px;
color:#8794a8}
.taxonomy-grid{display:grid;
