/* V34 — iPhone Dynamic Island / notch / home indicator. No fake Dynamic Island UI. */
@supports(padding-top:env(safe-area-inset-top)){
  @media(max-width:790px){
    .vive-mobile-top{
      box-sizing:border-box!important;
      height:calc(66px + env(safe-area-inset-top, 0px))!important;
      min-height:calc(66px + env(safe-area-inset-top, 0px))!important;
      padding-top:env(safe-area-inset-top, 0px)!important;
      padding-left:calc(17px + env(safe-area-inset-left, 0px))!important;
      padding-right:calc(17px + env(safe-area-inset-right, 0px))!important;
    }
    body[data-menu-layout='rail'] .main,body.vision-mode .main{
      padding-right:calc(14px + env(safe-area-inset-right, 0px))!important;
      padding-left:calc(14px + env(safe-area-inset-left, 0px))!important;
    }
    .vive-mobile-dock{
      left:calc(18px + env(safe-area-inset-left, 0px));
      right:calc(18px + env(safe-area-inset-right, 0px));
      bottom:calc(14px + env(safe-area-inset-bottom, 0px));
    }
    .f33-gate{
      padding:calc(18px + env(safe-area-inset-top, 0px))
              calc(18px + env(safe-area-inset-right, 0px))
              calc(18px + env(safe-area-inset-bottom, 0px))
              calc(18px + env(safe-area-inset-left, 0px));
    }
    .modal-layer{padding-top:calc(14px + env(safe-area-inset-top,0px))!important;
}
    .f33-auth-card input{font-size:16px;
}
  }
}
