body.theme-black #app .v273-settings-customizer .v747-premium-card,
body.theme-dark #app .v273-settings-customizer .v747-premium-card{
 border-color:rgba(var(--v747-rgb),.40)!important;box-shadow:inset 0 1px 0 rgba(255,255,255,.10),0 6px 19px rgba(0,0,0,.4)!important}
body:not(.theme-black):not(.theme-dark) #app .v273-settings-customizer .v747-premium-card{
