/* ==== v868-overview-fluid-layout ==== */
/* V868 · CICLO 01 / INICIO ONLY.
   Refinamiento de geometría sin cambiar datos, navegación, los dos temas ni acentos.
   Regla: adaptar a contenedores y contenido, sin escalar el cuerpo ni ocultar overflow.
*/
#app main.world-overview {
  --v868-space: clamp(8px, 1.6vw, 16px);
  --v868-control-min: 44px;
  min-width: 0;
}
#app main.world-overview #page,
#app main.world-overview :is(.ff-dashboard,.ff-dashboard-grid,.ff-mid,.ff-tile,.ff-panel-top,.ff-panel-top>div),
#app main.world-overview :is(.vive-mobile-home,.v732-heading-line,.vive-mobile-balance,.vive-mobile-commitments,.vive-mobile-dues,.v36-month-capsule) {
  min-width: 0;
  max-width: 100%;
  box-sizing: border-box;
}
#app main.world-overview :is(.ff-trans-main,.ff-pay-name,.ff-person-name,.v36-commitment-name),
#app main.world-overview :is(.ff-balance-header>div,.v36-commitment-detail-copy) { min-width: 0; }
#app main.world-overview :is(.ff-balance-total,.ff-person-sums strong,.ff-health-foot strong,.ff-pay-row>b),
#app main.world-overview :is(.vive-mobile-balance-amount,.v186-mobile-foot-amount,.vive-mobile-commitment-value,.vive-mobile-net-value,.v36-month-columns strong) {
  font-variant-numeric: tabular-nums;
  max-width: 100%;
}
/* Pantallas móviles: conservar la composición aprobada con espacio útil real. */
@media (max-width: 790px) {
  #app main.world-overview,
  #app main.world-overview .vive-mobile-home { min-width: 0; }
  #app main.world-overview .vive-mobile-home {
    width: 100%;
    max-width: 100%;
    box-sizing: border-box;
  }
  #app main.world-overview .v732-heading-line {
    min-width: 0;
    gap: clamp(6px, 1.8vw, 12px);
  }
  #app main.world-overview .v732-heading-line h1 {
    flex: 1 1 auto;
    min-width: 0;
    overflow-wrap: break-word;
  }
  #app main.world-overview :is(.vive-mobile-due-row,.v36-commitment-group summary,.v36-commitment-detail,.vive-mobile-card-head) > * {
    min-width: 0;
  }
  #app main.world-overview :is(.vive-mobile-quick-actions,.v36-month-columns,.v36-commitment-list,.vive-mobile-balance-foot) {
    max-width: 100%;
  }
  #app main.world-overview :is(.vive-mobile-quick-actions button,.v273-personalize-link,.vive-mobile-view-all) {
    min-height: var(--v868-control-min);
  }
  #app main.world-overview :is(.v732-period input,.v732-period button) {
    max-width: 100%;
  }
}
/* El ajuste se activa por anchura disponible y no por marca/modelo del teléfono. */
