/* ==== v913-wallet-accents-patch ==== */
/* V913 · Wallet móvil, acentos contextuales, navegación activa y coherencia de labels */
:root{
  --v913-ink:#243655;
  --v913-muted:#6f82a1;
  --v913-line:rgba(152,171,197,.28);
  --v913-accent:var(--accent, #6d6af8);
  --v913-accent-soft:color-mix(in srgb, var(--v913-accent) 9%, #ffffff);
  --v913-accent-soft-2:color-mix(in srgb, var(--v913-accent) 16%, #ffffff);
  --v913-green:#17a37a;
  --v913-red:#dd5b67;
}
/* Wallet móvil: tarjetas y detalles con acento superior derecho como Inicio/Bancos */
.v266-wallet-panel,
.v266-wallet-detail{
  position:relative;
  overflow:hidden;
  border:1px solid color-mix(in srgb, var(--v913-accent) 20%, #dfe7f1) !important;
  background:
    radial-gradient(170px 130px at 100% 0%, color-mix(in srgb, var(--v913-accent) 11%, transparent), transparent 74%),
    linear-gradient(180deg, rgba(255,255,255,.985), rgba(251,253,255,.985)) !important;
  box-shadow:0 10px 28px rgba(31,49,79,.055) !important;
}
.v266-wallet-panel::before,
.v266-wallet-detail::before{
  content:"";
  position:absolute;
  inset:0;
  pointer-events:none;
  background:linear-gradient(135deg, rgba(255,255,255,.22), rgba(255,255,255,0) 42%);
}
.v266-wallet-panel .v266-panel-heading,
.v266-wallet-detail summary{ position:relative; z-index:1; }
.v266-wallet-panel .v266-panel-heading button,
.v266-wallet-detail summary > svg,
.v266-wallet-detail summary > span svg{
  color:color-mix(in srgb, var(--v913-accent) 78%, #314867) !important;
}
.v266-wallet-panel .v266-panel-heading button,
.v266-wallet-detail summary > :last-child{
  background:rgba(255,255,255,.72);
  border:1px solid color-mix(in srgb, var(--v913-accent) 20%, #dbe4ee);
  box-shadow:0 6px 16px rgba(36,52,76,.05);
}
.v266-wallet-actions{
  gap:14px !important;
  grid-template-columns:repeat(4,minmax(0,1fr)) !important;
}
.v266-wallet-actions button{
  min-height:112px !important;
  border:1px solid color-mix(in srgb, var(--v913-accent) 18%, #dbe4ee) !important;
  box-shadow:0 8px 20px rgba(36,52,76,.04);
}
.v266-wallet-actions button span{
  width:62px !important;
  height:62px !important;
  border-radius:50%;
  display:grid !important;
  place-items:center;
  background:linear-gradient(180deg, rgba(255,255,255,.9), color-mix(in srgb, var(--v913-accent) 7%, #fff)) !important;
  border:1px solid color-mix(in srgb, var(--v913-accent) 18%, #dde5ef) !important;
}
.v266-wallet-actions button span svg{width:24px;height:24px}
.v266-wallet-actions button b{font-size:18px !important}
.v266-wallet-actions button[aria-label*="avance" i],
.v266-wallet-actions button[data-v900-action="advance"]{
  background:linear-gradient(180deg, color-mix(in srgb, var(--v913-accent) 84%, #ffffff), color-mix(in srgb, var(--v913-accent) 94%, #3843dc)) !important;
  color:#fff !important;
  border-color:transparent !important;
}
.v266-wallet-actions button[aria-label*="avance" i] span,
.v266-wallet-actions button[data-v900-action="advance"] span{
  background:rgba(255,255,255,.14) !important;
  border-color:rgba(255,255,255,.2) !important;
}
/* Actividad reciente y estado de tarjeta: iconos y filas mejor dimensionados */
.v266-wallet-panel.v266-activity .v266-panel-heading button,
.v266-wallet-panel .v266-panel-heading button{
  width:50px;height:50px;border-radius:50%;display:grid;place-items:center;
}
.v266-activity [class*="icon"],
.v266-wallet-detail summary span svg,
.v266-panel-heading button svg,
.v266-next-payment button svg{ width:21px; height:21px; }
/* Tarjetas activas y navegación superior en Bancos / Movimientos / módulos */
.module-switch-tab.active,
.subnav .active,
button[aria-current="page"],
[data-page].active{
  background:linear-gradient(180deg, color-mix(in srgb, var(--v913-accent) 82%, #ffffff), color-mix(in srgb, var(--v913-accent) 94%, #3a44de)) !important;
  color:#fff !important;
  border-color:transparent !important;
  box-shadow:0 14px 26px color-mix(in srgb, var(--v913-accent) 22%, transparent) !important;
}
.module-switch-tab.active svg,
.subnav .active svg,
button[aria-current="page"] svg{color:#fff !important;stroke:currentColor !important}
/* Explorar / Visión global / botones secundarios con coherencia de iconos y acento */
.v205-explore-grid [class*="arrow"],
.v410-explore-grid [class*="arrow"],
.v295-global-overview [class*="chart"],
.v306-global-desktop [class*="chart"],
.v708 [class*="chart"],
.v243-explore-return button,
.vive-mobile-view-all,
.v290-budget-head > button,
.v295-global-overview button,
.v306-global-desktop button{
  color:color-mix(in srgb, var(--v913-accent) 72%, #2f466a) !important;
}
/* Capacidad de endeudamiento: tono semántico sutil dentro del cuadrito */
.v105-capacity-grid .v105-capacity-rate{
  border:1px solid rgba(219,229,238,.95) !important;
  box-shadow:inset 0 1px 0 rgba(255,255,255,.55);
}
.v105-capacity-widget.v105-capacity-over .v105-capacity-rate{
  background:linear-gradient(180deg, rgba(255,255,255,.96), color-mix(in srgb, var(--v913-red) 10%, #fff)) !important;
  border-color:color-mix(in srgb, var(--v913-red) 22%, #dbe5ef) !important;
}
.v105-capacity-widget:not(.v105-capacity-over) .v105-capacity-rate{
  background:linear-gradient(180deg, rgba(255,255,255,.96), color-mix(in srgb, var(--v913-green) 10%, #fff)) !important;
  border-color:color-mix(in srgb, var(--v913-green) 22%, #dbe5ef) !important;
}
.v105-capacity-rate strong{
  display:inline-block;
  background:linear-gradient(180deg, color-mix(in srgb, var(--v913-red) 92%, #fff), color-mix(in srgb, var(--v913-red) 74%, #ad3047));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.v105-capacity-widget:not(.v105-capacity-over) .v105-capacity-rate strong{
  background:linear-gradient(180deg, color-mix(in srgb, var(--v913-green) 92%, #fff), color-mix(in srgb, var(--v913-green) 70%, #0f7e62));
  -webkit-background-clip:text; background-clip:text; color:transparent;
}
.v105-capacity-rate span{
  color:color-mix(in srgb, var(--v913-red) 74%, #7a5060) !important;
}
.v105-capacity-widget:not(.v105-capacity-over) .v105-capacity-rate span{
  color:color-mix(in srgb, var(--v913-green) 70%, #4f6d63) !important;
}
/* Inicio móvil: quitar la lectura de “cuadrito tapado”; devolver el fondo vivo detrás del resumen */
.v273-overview-widget,
.v105-capacity-widget,
.v266-wallet-panel,
.v266-wallet-detail,
.v295-global-overview .panel,
.v306-global-desktop .panel{
  backdrop-filter:blur(14px);
}
/* Otros / editar / recibir / mover / pagar: iconos coherentes */
.vr-operation-icon,
.v29-other-icon,
.v244-action svg,
.v244-action-primary svg{
  width:22px !important; height:22px !important;
}
.vr-operation,
.v29-other-action{ align-items:center !important; }
.vr-operation-icon,
.v29-other-icon{
  width:46px !important; height:46px !important; border-radius:16px !important; display:grid !important; place-items:center;
}
/* Cumplimiento del presupuesto en Inicio web: más alineado con la familia predominante */
.v290-budget-web .v290-budget-head > button{
  background:rgba(255,255,255,.72) !important; border:1px solid color-mix(in srgb, var(--v913-accent) 20%, #dbe4ee) !important; border-radius:999px;
}
/* Tema black */
body.theme-black .v266-wallet-panel,
body.theme-black .v266-wallet-detail,
body.theme-dark .v266-wallet-panel,
body.theme-dark .v266-wallet-detail{
  background:
    radial-gradient(170px 130px at 100% 0%, color-mix(in srgb, var(--v913-accent) 15%, transparent), transparent 74%),
    linear-gradient(180deg, rgba(13,13,13,.98), rgba(9,9,9,.98)) !important;
  border-color:color-mix(in srgb, var(--v913-accent) 18%, #2b2f35) !important;
  box-shadow:0 14px 32px rgba(0,0,0,.46) !important;
}
@media (max-width: 790px){
  .v266-wallet-actions button{min-height:104px !important}
}
