  .ff-balance.ff-tile,.ff-expense-card.ff-tile,.ff-upcoming.ff-tile,.ff-personal.ff-tile,.ff-obligation-total,.v290-budget-web
),
html body:not(.theme-black):not(.theme-dark) #app .main.world-advanced #page .advanced-quick.v14-advanced-three > .advanced-stat.v16-annual-clean,
html body:not(.theme-black):not(.theme-dark) #app .main:is(
 .world-advanced,.world-analytics,.world-banks,.world-accounts,.world-cards,
 .world-loans,.world-certificates,.world-patrimony,.world-vision,.world-payments,
 .world-personal,.world-recurring,.world-income,.world-expenses,.world-budget,
 .world-register,.world-transactions,.world-categories,.world-benefits,.world-mobilehub,.world-pressure
) #page :is(
  .panel:not(.featured):not(.v390-hero):not(.personal-hero):not(.v390-personal-hero),.kpi:not(.featured),
  .panel:not(.featured):not(.v390-hero):not(.personal-hero):not(.v390-personal-hero),.kpi:not(.featured),
