  .v239-sheet,.v239-account-item,.v239-certificate-item,.v244-sheet,
  .v22-wealth-chart,.v22-wealth-balance,.v22-forecast-kpi,
  .v46-subscription-card,.v145-payment-section,.v295-payment-section,
  .v187-chart-card,.v187-benefits-ledger,.v55-panel,.v55-metric,
  .v205-explore-group,.v410-explore-sec,.v431-tile,
  .bank-card,.account-card,.loan-card,.certificate-card,
  .credit-box,.analytics-card,.budget-analysis-panel,.budget-variance-card,
  .v200-pay-tool,.v145-payment-kpi,.v145-pay-agenda,.v145-pay-quick,
  .v296-preview-card,.v332-preview-card,.v273-overview-widget
):not(.active):not(.selected):not(.featured):not(.danger):not(.warning),
html body:not(.theme-black):not(.theme-dark) #app :is(
  .vive-mobile-home .v273-overview-widget,.vive-mobile-home .v318-mobile-card,
  .vive-mobile-home .v105-capacity-widget,.vive-mobile-home .v290-budget-mobile,
