/* ==== vhe-menu-interior-only ==== */
/*Refinamiento EXCLUSIVAMENTE dentro de #page. No modifica barra, navegación, topbar ni fondos globales.*/
#page .inner-menu {
  display: flex;
  flex-wrap: wrap;
  align-items: center;
  gap: 12px;
  justify-content: space-between;
  background: rgba(255,255,255,.72);
  border: 1px solid rgba(255,255,255,.98);
  backdrop-filter: blur(18px);
  -webkit-backdrop-filter: blur(18px);
  border-radius: 19px;
  padding: 12px 14px;
  margin: 0 0 19px;
  box-shadow: 0 8px 28px rgba(30,67,113,.045);
}
#page .inner-menu-caption {
  display: flex;
  flex-direction: column;
  gap: 3px;
  flex: 0 1 155px;
  min-width: 120px;
}
#page .inner-menu-caption b {
  font-size: 12px;
  color: color-mix(in srgb,var(--v424-accent-strong,#5a6b86) 16%,#3b4556);
  letter-spacing: -.2px;
}
#page .inner-menu-caption small {
  font-size: 10px;
  color: #92a2b4;
}
#page .inner-menu-tabs {
  align-items: center;
  flex: 1;
  min-width: 0;
  flex-wrap: wrap;
}
#page .inner-menu-tab {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  gap: 7px;
  min-height: 35px;
  border-radius: 11px;
  padding: 8px 12px;
  border: 1px solid transparent;
  background: transparent;
  color: #71839a;
  font-size: 11px;
  font-weight: 730;
  white-space: nowrap;
  transition: .16s;
}
#page .inner-menu-tab:hover {
  background: #f0f4fb;
  color: #305da3;
}
#page .inner-menu-tab.active {
  background: #eaf1ff;
  border-color: #dce8ff;
  color: #3464bd;
  box-shadow: 0 2px 7px rgba(47,86,154,.06);
}
#page .inner-menu-tab:focus-visible {
  outline: 3px solid #9ec2ff;
  outline-offset: 2px;
}
#page .inner-menu-button {
  display: inline-flex;
  gap: 7px;
  align-items: center;
  justify-content: center;
  background: #2c69cc;
  color: #fff;
  border: 0;
  padding: 10px 12px;
  border-radius: 11px;
  font-size: 11px;
  font-weight: 780;
  white-space: nowrap;
}
#page .inner-menu-button:hover {
  background: #215aa9;
}
#page .inner-view {
  display: grid;
  gap: 15px;
  min-width: 0;
  animation: inner-appear .16s ease-out;
}
#page .inner-view-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  gap: 10px;
  flex-wrap: wrap;
}
#page .inner-view-header h2 {
  margin: 0;
  font-size: 19px;
  font-weight: 760;
  letter-spacing: -.5px;
  color: #294460;
}
#page .inner-view-header p {
  margin: 5px 0 0;
  font-size: 11px;
  color: #8799ad;
  line-height: 1.5;
}
#page .inner-view-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill,minmax(235px,1fr));
