}
#page .inner-view-card {
  background: rgba(255,255,255,.79);
  border: 1px solid #fff;
  border-radius: 19px;
  padding: 18px;
  box-shadow: 0 7px 24px #1c4c8810;
  min-width: 0;
}
#page .inner-view-card .inner-eyebrow {
  font-size: 10px;
  font-weight: 730;
  color: #8d9caf;
  letter-spacing: .6px;
