#page .inner-category .track {
  height: 7px;
  background: #ebf1f8;
  border-radius: 20px;
  overflow: hidden;
}
#page .inner-category .track span {
  display: block;
  height: 100%;
  background: #719ce6;
  border-radius: 20px;
}
#page .inner-category .money {
  color: #426181;
}
@keyframes inner-appear {
  from {
    opacity: .75;
    transform: translateY(4px);
