/* ==== vive-v109-mobile-continuity-only ==== */
/* V109 — Continuidad visual desde la parte superior, SOLO móvil.
   Mantiene la navegación, jerarquías, tema y todo el JavaScript original. */
@media screen and (max-width:790px) {
  /* El área superior acompaña el fondo de la página: sin una barra
     de otro color ni un borde horizontal que corte la composición. */
  html { background-color:#dce9fa; }
  .vive-mobile-top {
    border:0!important;
    border-top:0!important;
    border-bottom:0!important;
    outline:0!important;
    box-shadow:none!important;
    -webkit-backdrop-filter:none!important;
    backdrop-filter:none!important;
  }
  /* Continuidad real: el encabezado deja ver el mismo fondo
     de la página, sin una banda de color independiente. */
  body:not(.theme-dark):not(.vision-mode) .vive-mobile-top,
  body.theme-dark:not(.vision-mode) .vive-mobile-top,
  body.vision-mode .vive-mobile-top {
    background:transparent!important;
    background-color:transparent!important;
  }
  .main > .topbar,
  #page > .topbar,
  #page > .section-title {
    border-top:0!important;
    border-bottom:0!important;
    box-shadow:none!important;
  }
  /* Los formularios móviles comparten el mismo fondo visual de su
     contenido, sin rayas divisorias bajo la cabecera. */
  #modal-root .modal-head,
  #modal-root .mqr-header {
    background:#f4f7fb!important;
    border:0!important;
    border-top:0!important;
    border-bottom:0!important;
    box-shadow:none!important;
    -webkit-backdrop-filter:none!important;
    backdrop-filter:none!important;
  }
  #modal-root .fastx-head,
  #modal-root .other-studio-header {
    border-bottom:0!important;
    box-shadow:none!important;
  }
  /* Adaptación a los dos modos oscuros existentes, sin forzar blanco. */
  body.theme-dark:not(.vision-mode) #modal-root .modal-head,
  body.theme-dark:not(.vision-mode) #modal-root .mqr-header {
    background:#16243b!important;
  }
  body.vision-mode #modal-root .modal-head,
  body.vision-mode #modal-root .mqr-header {
    background:#15243a!important;
  }
}
