/* ==== v215-responsive-adaptive-layer ==== */
/* ============================================================================
   V215 · CAPA DE ADAPTABILIDAD Y LEGIBILIDAD NO DESTRUCTIVA
   Mantiene estilos, colores, jerarquías y comportamientos originales.
   Solo corrige límites físicos de viewport, wrapping y mínimos intrínsecos.
   ============================================================================ */
@supports (width: min(100%, 1px)) {
  html { max-width: 100%; }
  body { max-width: 100%; }
  /* Permite que los hijos de flex/grid reduzcan su ancho intrínseco. */
  :is(.main, #page, .content, .page-content, .dashboard, .dashboard-content,
      .summary-content, .resumen-content, .panel-content, .module-content) {
    min-width: 0;
  }
  /* Multimedia nunca fuerza el desbordamiento del panel que la contiene. */
  :is(.main, #page) :is(img, video, canvas, svg) { max-width: 100%; }
  :is(.main, #page) :is(input, textarea, select) { max-width: 100%; }
  :is(.main, #page) :is(h1, h2, h3, h4, p) { overflow-wrap: break-word; }
}
/* Los contenedores de tarjetas existentes pueden contraerse sin cambiar columnas. */
@supports (container-type: inline-size) {
  :is(.main, #page) :is(.card, .kpi-card, .metric-card, .glass-card) {
    min-width: 0;
  }
}
/* Ajustes para ventanas de escritorio compactas y zoom alto.
   Se preservan explícitamente las rejillas y proporciones existentes. */
@media (min-width: 768px) and (max-width: 1536px) {
  :is(.main, #page) :is(.card, .kpi-card, .metric-card, .glass-card,
      .panel, .widget) { min-width: 0; }
  :is(.main, #page) :is(.card, .kpi-card, .metric-card, .glass-card)
    :is(h1, h2, h3, h4, p, small, .title, .subtitle) { min-width: 0; }
}
@media (max-width: 767px) {
  :is(.main, #page) :is(.card, .kpi-card, .metric-card, .glass-card,
      .panel, .widget) { min-width: 0; }
  :is(.main, #page) :is(button, a, input, select, textarea) {
    -webkit-tap-highlight-color: transparent;
  }
}
/* Accesibilidad de movimiento: no afecta a usuarios sin esta preferencia. */
@media (prefers-reduced-motion: reduce) {
  :is(.main, #page) { scroll-behavior: auto; }
}
