}
.ant-hero {
  display: grid;
  grid-template-columns: minmax(0,1.05fr) minmax(0,1fr);
  border: 1px solid rgba(223,233,255,.57);
  border-radius: 28px;
  background: linear-gradient(125deg,#1c3154,#335a91);
  color: white;
