/*V290 · Diseño ejecutivo de presupuesto. Scope: Resumen y Personalización.*/
.v290-budget-web,.v290-budget-trend {
  --v290-ink: #213d61;
  --v290-muted: #7589a6;
  --v290-accent: #5a70dc;
  --v290-good: #0f957c;
  --v290-warning: #b7364c;
  --v290-danger: #c65b5a;
  box-sizing: border-box;
  min-width: 0;
}
.v290-budget-web *,.v290-budget-trend * {
  box-sizing: border-box;
}
.v290-budget-web {
  display: flex;
  flex-direction: column;
  gap: 7px;
  border-radius: 24px;
  background: linear-gradient(132deg,#f4f7ff,#e7efff) !important;
  border: 1px solid rgba(255,255,255,.9) !important;
  box-shadow: 0 10px 26px rgba(75,100,165,.09) !important;
  padding: 13px 16px !important;
  overflow: hidden;
}
.v290-budget-head,.v290-mobile-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  gap: 10px;
  min-width: 0;
}
.v290-eyebrow {
  display: block;
  font-size: 8px;
  line-height: 1.3;
  letter-spacing: .11em;
  font-weight: 800;
  color: #6c7fa3;
  text-transform: uppercase;
}
.v290-budget-head h2,.v290-mobile-header h2 {
  font-size: clamp(16px,1.5vw,20px);
  font-weight: 820;
  letter-spacing: -.05em;
  margin: 3px 0 0;
  color: #213d61;
  line-height: 1.15;
}
.v290-budget-head button,.v290-mobile-header button {
  border: 0;
  background: rgba(255,255,255,.75);
  color: #506ca6;
  font-size: 10px;
  font-weight: 780;
  border-radius: 10px;
  padding: 7px 9px;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 3px;
  flex-shrink: 0;
}
.v290-budget-head svg,.v290-mobile-header svg {
  width: 14px;
  height: 14px;
}
.v290-ring {
  --v290-angle: 0deg;
  flex: 0 0 auto;
  width: clamp(64px,6.3vw,85px);
  height: clamp(64px,6.3vw,85px);
  border-radius: 50%;
