    inset:auto auto var(--v340-nav-inset) 50%!important;
    right:auto!important;
    left:50%!important;
    transform:translate3d(-50%,0,0)!important;
    margin:0!important;
    box-sizing:border-box!important;
    display:flex!important;
    flex-flow:row nowrap!important;
    align-items:center!important;
    justify-content:space-between!important;
    isolation:isolate;
    backface-visibility:hidden;
    -webkit-backface-visibility:hidden;
    /* El fondo no debe desaparecer al desplazar tarjetas por debajo. */
    box-shadow:0 10px 24px rgba(0,0,0,.13),inset 0 1px 0 rgba(255,255,255,.40)!important;
  }
  body .vive-mobile-dock>.vive-mobile-dock-item{
    flex:1 1 0!important;
    width:0!important;
    max-width:none!important;
    margin:0!important;
    display:flex!important;
    flex-direction:column!important;
    align-items:center!important;
    justify-content:center!important;
    overflow:hidden!important;
    transform:none!important;
  }
  body .vive-mobile-dock>.vive-mobile-dock-item:active{transform:scale(.97)!important;}
  body .vive-mobile-dock .vive-mobile-dock-icon{
    display:flex!important;
