    justify-content:center!important;
    width:100%!important;
  }
  body .vive-mobile-dock .vive-mobile-dock-icon svg{flex-shrink:0!important;}
  body .vive-mobile-dock .vive-mobile-dock-label{
    display:block!important;
    max-width:100%!important;
    white-space:nowrap!important;
    overflow:hidden!important;
    text-overflow:clip!important;
  }
  /* Visibilidad y legibilidad de Liquid Glass mientras el contenido se desplaza. */
  body:not(.theme-black):not(.theme-dark) .vive-mobile-dock{
    background:rgba(255,255,255,calc(.72 + var(--v250-dock-opacity,.37) * .22))!important;
    background-image:radial-gradient(ellipse at 85% 15%,color-mix(in srgb,var(--vive-theme-color,#665fe7) 8%,transparent) 0%,color-mix(in srgb,var(--vive-theme-color,#665fe7) 3%,transparent) 45%,transparent 78%)!important;
    border:1px solid rgba(255,255,255,.90)!important;
    -webkit-backdrop-filter:blur(var(--v250-dock-blur,20px)) saturate(var(--v250-dock-saturation,150%))!important;
