 --v440-light:color-mix(in srgb,var(--v440-accent) 46%,#ccdfff 54%);
 --v440-shadow:color-mix(in srgb,var(--v440-accent) 18%,transparent);
 --v440-matte:color-mix(in srgb,var(--v440-accent) 13%,white 87%);
 --v440-sheen:linear-gradient(113deg,transparent 0%,rgba(255,255,255,.06) 47%,rgba(255,255,255,.14) 49%,transparent 62%);
}
