    box-shadow:none!important;backdrop-filter:none!important;-webkit-backdrop-filter:none!important;
    color:var(--v560-accent,var(--vive-theme-color,#496bb7))!important;
    -webkit-text-fill-color:currentColor!important;
    font-size:12px!important;font-weight:720!important;
  }
  html body #app .main .vive-mobile-greeting .v273-personalize-link .v309-personalize-symbol{
    width:21px!important;height:21px!important;flex:0 0 21px!important;
    border:0!important;border-radius:0!important;background:transparent!important;
    box-shadow:none!important;color:inherit!important;
  }
  html body #app .main .vive-mobile-greeting .v273-personalize-link svg{
    width:19px!important;height:19px!important;stroke:currentColor!important;
    color:inherit!important;
  }
  html body #app .main .vive-mobile-greeting .v273-personalize-link:is(:hover,:focus-visible){
    color:var(--v560-accent,var(--vive-theme-color,#496bb7))!important;
