/* V876 · Complemento cromático móvil del Paso 3.
   Un único origen: --vive-theme-color. Sin ajustes de datos, gráficas semánticas
   ni dimensiones de escritorio. Los fallbacks originales conservan web intacta. */
@media (max-width:790px){
 body{
  --v876-accent-source:var(--v7-accent);
  --v876-trend-main:var(--v7-chart-main);
  --v876-accent-glow:var(--v7-accent-surface);
  --v876-accent-border:var(--v7-accent-border);
  --v876-credit-progress:linear-gradient(90deg,color-mix(in srgb,var(--v876-accent-source) 70%,#24365e),var(--v876-accent-source));
  --v876-heat-1:var(--v7-chart-1);
  --v876-heat-2:var(--v7-chart-2);
  --v876-heat-3:var(--v7-chart-3);
  --v876-heat-4:var(--v7-chart-4);
  --v876-preview-highlight:color-mix(in srgb,var(--v876-accent-source) 32%,#fff);
  --v876-preview-base:color-mix(in srgb,var(--v876-accent-source) 80%,#27375a);
  --v876-preview-area:color-mix(in srgb,var(--v876-accent-source) 42%,#fff);
  --v876-preview-area-end:color-mix(in srgb,var(--v876-accent-source) 78%,#243858);
  --v876-preview-halo:var(--v876-accent-source);
 }
 body:is(.theme-black,.theme-dark){
  --v876-trend-main:var(--v7-chart-main);
  --v876-accent-glow:var(--v7-accent-surface);
  --v876-accent-border:var(--v7-accent-border);
  --v876-heat-1:var(--v7-chart-1);
  --v876-heat-2:var(--v7-chart-2);
  --v876-heat-3:var(--v7-chart-3);
  --v876-heat-4:var(--v7-chart-4);
  --v876-preview-highlight:color-mix(in srgb,var(--v876-accent-source) 54%,#edf1ff);
  --v876-preview-base:color-mix(in srgb,var(--v876-accent-source) 63%,#212138);
  --v876-preview-area:color-mix(in srgb,var(--v876-accent-source) 55%,#30354e);
  --v876-preview-area-end:color-mix(in srgb,var(--v876-accent-source) 60%,#151a29);
 }
 /* Patrimonio: resaltado de foco y leyenda, sin teñir el histórico ni previsiones de riesgo. */
