 body:is(.theme-black,.theme-dark) .v317-heat-grid .v317-heat-cell:is(.heat-3,.heat-4) span{color:#f5f7fc!important}
 .v317-heat-grid{gap:clamp(4px,1.45vw,7px)!important}
 .v317-heat-grid .v317-heat-cell{border-radius:clamp(7px,2vw,9px)!important}
 .v317-heat-grid .v317-heat-cell:focus-visible{
   outline:2px solid var(--v876-trend-main)!important;outline-offset:2px;
 }
 /* Black: ganan a los overrides generales de botones, sin teñir el nivel vacío. */
 html body:is(.theme-black,.theme-dark) #app #page .v317-heat-grid button.v317-heat-cell.heat-1{background:var(--v876-heat-1)!important}
 html body:is(.theme-black,.theme-dark) #app #page .v317-heat-grid button.v317-heat-cell.heat-2{background:var(--v876-heat-2)!important}
 html body:is(.theme-black,.theme-dark) #app #page .v317-heat-grid button.v317-heat-cell.heat-3{background:var(--v876-heat-3)!important}
