/* ==== v950-responsive-engine ==== */
/* ==========================================================================
   V950 · Motor responsive fluido y autodimensionable
   --------------------------------------------------------------------------
   Capa final de la cascada. NO redefine la identidad visual: conserva por
   separado el diseño móvil (≤790px) y el de escritorio (≥791px) y solo:
     1. Declara tokens fluidos (clamp) reutilizables.
     2. Añade salvaguardas globales contra desbordes (media, texto, formularios,
        hijos de grid/flex) con especificidad cero (:where) para no pisar
        reglas existentes.
     3. Convierte componentes clave en contenedores (Container Queries) para
        que reaccionen a SU propio ancho, no al del dispositivo.
     4. Corrige desalineaciones y desbordes medidos en 320–2560px.
   ========================================================================== */

/* 1 · Tokens fluidos ------------------------------------------------------ */
:root{
 --rx-gutter:clamp(12px,1.6vw + 6px,32px);
 --rx-gap:clamp(8px,.9vw + 5px,20px);
 --rx-radius:clamp(14px,.8vw + 10px,24px);
 --rx-tap:44px;
 --rx-content-max:1800px;
 --rx-safe-l:env(safe-area-inset-left,0px);
 --rx-safe-r:env(safe-area-inset-right,0px);
 --rx-safe-b:env(safe-area-inset-bottom,0px);
}

/* 2 · Salvaguardas globales (especificidad 0) ----------------------------- */
html{-webkit-text-size-adjust:100%;text-size-adjust:100%}
/* Nunca debe existir scroll horizontal de página; clip no rompe position:sticky. */
body{overflow-x:clip}
:where(#app,#modal-root,.modal-layer) :where(img,video,canvas,iframe,picture){max-width:100%}
:where(#app,#modal-root,.modal-layer) :where(input,select,textarea){max-width:100%;min-width:0}
:where(#app main,#modal-root,.modal-layer) :where(h1,h2,h3,h4,h5,p,li,dt,dd,label,figcaption,blockquote){overflow-wrap:break-word}
/* Hijos de rejillas y filas: pueden encogerse en lugar de empujar fuera del contenedor. */
:where(#app main) :where([class*="grid"],[class*="-row"],[class*="kpis"],[class*="-cols"],[class*="columns"],[class*="-stack"])>:where(*){min-width:0}
/* Tablas: siempre dentro de su propio scroll si no caben. */
:where(#app main) :where(.table-wrap,[class*="table-scroll"],[class*="-scroll"]){max-width:100%}
/* Ventanas modales: nunca más grandes que la pantalla visible. */
:where(.modal-layer,#modal-root) :where(.modal,[role="dialog"]){max-width:calc(100vw - var(--rx-safe-l) - var(--rx-safe-r));max-height:100dvh}

/* 3 · Contenedores (Container Queries) ------------------------------------ */
html body #app .ff-dashboard .v152-position-reference,
html body #app .theme-settings.panel,
html body #app .v431-explore .v431-tile,
html body #app .v443-nav-settings{container-type:inline-size}
html body #app .ff-dashboard .v152-position-reference{container-name:rx-position}
html body #app .theme-settings.panel{container-name:rx-theme}

/* Posición financiera (escritorio): si la tarjeta es estrecha, los botones
   "Recibir dinero / Registrar egreso" bajan al flujo en vez de pisar las burbujas. */
@container rx-position (max-width:860px){
 html body #app .main .ff-dashboard.summary-space .v152-position-reference .ff-balance-actions{
  position:static!important;inset:auto!important;justify-content:flex-end!important;
  flex-wrap:wrap!important;gap:8px!important;margin-top:10px!important;padding-top:0!important;
 }
}
/* Burbujas proporcionales al ancho de su tarjeta (sin cambiar su forma). */
@container rx-position (max-width:560px){
 html body #app .ff-dashboard .ff-bubbles .ff-bubble{width:clamp(96px,27cqi,133px)!important;height:clamp(96px,27cqi,133px)!important}
 html body #app .ff-dashboard .ff-bubbles .ff-bubble.featured{width:clamp(108px,31cqi,153px)!important;height:clamp(108px,31cqi,153px)!important}
}

