html body #modal-root .v749-sheet-inner:focus-visible{outline:2px solid var(--v749-accent,#7165ee);outline-offset:-2px}
/* ==== v954-safe-vars ==== */
/* V954 · Zonas seguras como variables: una sola fuente (env) y valores comprobables en pruebas. */
:root{--v954-safe-top:env(safe-area-inset-top,0px);--v954-safe-bottom:env(safe-area-inset-bottom,0px)}
/* ==== v953-registrar-finish ==== */
/* ==========================================================================
   V953 · Cierre del flujo REGISTRAR (web y móvil)
   Solo presentación: legibilidad, áreas táctiles, ajuste a 100dvh y bloqueo
   del fondo. No cambia cálculos, datos ni reglas de negocio.
   ========================================================================== */
:root{
 --v953-ink:#0f172a;          /* texto principal casi negro */
 --v953-muted:#45556e;        /* texto secundario ≥ 6:1 sobre fondos claros */
 --v953-line:#c3cddc;         /* borde visible de campos */
 --v953-field:#ffffff;        /* fondo de campos */
 --v953-danger:#b42335;       /* déficit / error legible */
 --v953-tap:44px;             /* área táctil mínima */
 --v953-radius:12px;
 --v953-gap:clamp(4px,1dvh,9px);
}
/* Fondo bloqueado mientras haya una capa abierta en #modal-root (se libera al cerrarla). */
html:has(#modal-root>*),html:has(#modal-root>*) body{overflow:hidden!important;overscroll-behavior:none}

/* ---------- Legibilidad (tema claro) ---------- */
html body:not(.theme-dark):not(.theme-black) #modal-root :is(.v749-subtitle,.v749-amount small,.v749-impact small,.v749-illustrated p,.v749-confirm-row>span,.v749-illustrated small){color:var(--v953-muted)!important;-webkit-text-fill-color:var(--v953-muted)!important}
html body:not(.theme-dark):not(.theme-black) #modal-root .v749-deficit strong{color:var(--v953-danger)!important;-webkit-text-fill-color:var(--v953-danger)!important}
