html body:not(.theme-dark):not(.theme-black) #modal-root .v749-mid{color:var(--v424-accent-strong)!important}
html body #modal-root .v749-scroll>.v749-error{margin:2px 4px 6px!important;font-size:12px!important;font-weight:650!important;line-height:1.3!important}
html body #modal-root .v749-error:empty{display:none!important}
/* Botón principal: mismo morado, un tono más profundo para que el texto blanco supere 4.5:1. */
html body #modal-root .v749-layer[data-v749-stage] .v749-primary{min-height:var(--v953-tap)!important}
html body:not(.theme-dark):not(.theme-black) #modal-root .v749-primary:not(:disabled){background:linear-gradient(120deg,var(--v424-accent-strong),color-mix(in srgb,var(--v424-accent-strong) 82%,#fff))!important;color:#fff!important}

/* ---------- Campos: fondo blanco, borde visible, texto casi negro ---------- */
