 background:radial-gradient(130% 90% at 100% -10%,rgba(var(--tint),.2),transparent 55%),linear-gradient(180deg,rgba(255,255,255,.94),rgba(255,255,255,.72));
 border:1px solid rgba(255,255,255,.95);box-shadow:0 22px 40px -28px rgba(var(--tint),.55),inset 0 1px 0 #fff;-webkit-backdrop-filter:blur(18px) saturate(1.4);backdrop-filter:blur(18px) saturate(1.4);overflow:hidden}
