.v985-body{display:flex;flex-direction:column;gap:2px;min-width:0}
.v985-body.v985-row{flex-direction:row;align-items:center;justify-content:space-between;gap:10px}
.v985-figure{display:flex;flex-direction:column;gap:2px;min-width:0}
