.v985-spark{display:block;width:100%;height:56px;margin-top:4px;color:var(--t)}
.v985-stats{display:grid;grid-template-columns:1fr 1fr;gap:0;padding-top:10px;border-top:1px solid rgba(var(--tint),.2)}
.v985-stat{display:flex;align-items:center;gap:8px;min-width:0;padding:0 8px}.v985-stat+.v985-stat{border-left:1px solid rgba(var(--tint),.2)}
