.v985-minis{display:grid;gap:8px}
.v985-minis-4{grid-template-columns:repeat(4,minmax(0,1fr))}
.v985-minis-2{grid-template-columns:repeat(2,minmax(0,1fr))}
.v985-minis-3{grid-template-columns:repeat(3,minmax(0,1fr))}
.v985-mini{display:flex;flex-direction:column;align-items:center;justify-content:flex-start;gap:5px;min-width:0;min-height:76px;padding:11px 4px 9px;border-radius:18px;border:1px solid rgba(255,255,255,.95);background:rgba(255,255,255,.8);box-shadow:0 12px 20px -16px rgba(var(--tint),.7),inset 0 1px 0 #fff;color:#1c1f26;font:inherit;cursor:pointer;text-align:center}
