.v985-purple .v985-flat .v985-mini{background:rgba(154,59,232,.06);border-color:rgba(154,59,232,.1);box-shadow:none}
.v985-ring{position:relative;flex:0 0 96px;width:96px;height:96px;display:grid;place-items:center}
.v985-ring svg{position:absolute;inset:0;width:100%;height:100%}
